  expect(result[0]).toEqual({
    code: 'line-item/item',
    unitPrice: new Money(10000, 'EUR'),
    quantity: 3,
    includeFor: ['customer', 'provider'],
  });

  // Check shipping line item
  expect(result[1]).toEqual({
    code: 'line-item/shipping-fee',
    unitPrice: new Money(900, 'EUR'), // €5.00 + (2 * €2.00) = €9.00
    quantity: 1,
    includeFor: ['customer', 'provider'],
  });
});
